#!/usr/bin/env node
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { loadConfig } from "./config.js";
import { createTokenProvider } from "./auth.js";
import { loadOpenApi } from "./openapi-loader.js";
import { filterTools, generateTools } from "./tools.js";
import { createServer, SERVER_NAME } from "./server.js";

function log(message: string): void {
  process.stderr.write(`[mealie-mcp] ${message}\n`);
}

/** Read this package's version from package.json (single source of truth). */
function readVersion(): string {
  try {
    const pkgPath = join(dirname(fileURLToPath(import.meta.url)), "..", "package.json");
    return JSON.parse(readFileSync(pkgPath, "utf8")).version ?? "0.0.0";
  } catch {
    return "0.0.0";
  }
}

async function main(): Promise<void> {
  const config = loadConfig();
  const version = readVersion();

  const { doc, source } = await loadOpenApi(config);
  const allTools = generateTools(doc, config.toolNameMax);
  const tools = filterTools(allTools, config);

  if (tools.length === 0) {
    log("Warning: no tools matched your include/exclude filters. The server will expose nothing.");
  }

  // ⚡ Bolt: Use for...of to initialize the Set instead of Set(arr.map(...))
  // to avoid intermediate array allocations overhead.
  const categories = new Set<string>();
  for (const t of tools) categories.add(t.category);

  log(`${SERVER_NAME} v${version}`);
  log(`Mealie: ${config.baseUrl} | spec: ${source} (${doc.info?.version ?? "unknown"} version)`);
  log(`Exposing ${tools.length}/${allTools.length} tools across ${categories.size} categories.`);
  if (config.oauth) {
    log("Auth: OAuth2 client credentials (access token fetched from the IdP).");
    if (config.token) log("Note: MEALIE_API_TOKEN is ignored because OAuth is configured.");
  } else if (config.token) {
    log("Auth: static MEALIE_API_TOKEN.");
  } else {
    log("No credentials set — only unauthenticated endpoints will succeed.");
  }

  const auth = createTokenProvider(config);
  const server = createServer(config, tools, version, auth);
  const transport = new StdioServerTransport();
  await server.connect(transport);
  log("Server ready on stdio.");
}

main().catch((err) => {
  // SECURITY: Do not leak stack traces in error output to prevent exposing internals
  const reason = err instanceof Error ? err.message : String(err);
  process.stderr.write(`[mealie-mcp] Fatal: ${reason}\n`);
  process.exit(1);
});

// Runtime configuration, sourced entirely from environment variables so the
// server works cleanly as an `npx` stdio process launched by an MCP client.

export interface OAuthConfig {
  /** IdP token endpoint to POST the client-credentials grant to. */
  tokenUrl: string;
  clientId: string;
  clientSecret: string;
  /** Optional space-delimited scopes. */
  scope?: string;
  /** Optional audience (some IdPs, e.g. Auth0, require it to mint a Mealie-targeted token). */
  audience?: string;
}

export interface Config {
  /** Base URL of the Mealie instance, e.g. https://mealie.example.com. */
  baseUrl: string;
  /** Long-lived Mealie API token (Authorization: Bearer <token>). Optional but most endpoints need it. */
  token?: string;
  /**
   * OAuth2 client-credentials config. When set it takes precedence over `token`:
   * the server obtains (and refreshes) an access token from the IdP and sends it
   * as the Bearer credential. Requires a Mealie that validates IdP tokens (JWKS).
   */
  oauth?: OAuthConfig;
  /** Where to load the OpenAPI spec from. Defaults to `${baseUrl}/openapi.json`. */
  openapiUrl?: string;
  /** Skip the live fetch and always use the snapshot bundled with the package. */
  useBundledSpec: boolean;
  /** Only expose read (GET) endpoints. Useful for safe, read-only deployments. */
  readOnly: boolean;
  /** Whitelist of tool names and/or category slugs to include. Empty = include all (within the safe baseline). */
  include: string[];
  /** Blacklist of tool names and/or category slugs to exclude (on top of the always-on baseline trim). */
  exclude: string[];
  /** Per-request timeout in milliseconds. */
  timeoutMs: number;
  /** Optional default Accept-Language header forwarded to Mealie. */
  acceptLanguage?: string;
  /**
   * Maximum length for generated tool names. Kept low by default because many
   * MCP clients prefix tool names (e.g. `mcp__<server>__<tool>`) and the
   * combined string must stay within the 64-char API limit. Lower this further
   * if your client adds a long prefix.
   */
  toolNameMax: number;
  /** Log each outgoing request (method, path, status) to stderr for troubleshooting. */
  debug: boolean;
  /**
   * Extra attempts for idempotent (GET) requests that fail with a network error
   * or a retryable status (429/5xx). 0 disables retries. Non-GET methods are
   * never retried automatically because they may not be safe to repeat.
   */
  retries: number;
  /**
   * Directories that multipart file uploads may read from. Empty (the default)
   * means uploads are disabled for security. Setting it opts into an allowlist:
   * an upload whose real path — after symlinks are resolved — falls outside
   * every entry is refused.
   */
  allowedUploadDirs: string[];
}

/** Default cap for generated tool names; shared with the tool generator. */
export const DEFAULT_TOOL_NAME_MAX = 50;
const DEFAULT_RETRIES = 2;
const MAX_RETRIES = 5;

export function bool(value: string | undefined, fallback = false): boolean {
  if (value === undefined) return fallback;
  return /^(1|true|yes|on)$/i.test(value.trim());
}

export function list(value: string | undefined): string[] {
  if (!value) return [];
  return value
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
}

function parseBaseUrl(env: NodeJS.ProcessEnv): string {
  const rawBase = env.MEALIE_BASE_URL?.trim();
  if (!rawBase) {
    throw new Error(
      "MEALIE_BASE_URL is required (e.g. https://mealie.example.com). " +
        "Set it in your MCP client config under the server's `env`.",
    );
  }
  const baseUrl = rawBase.replace(/\/+$/, "");
  try {
    // Fail fast with a clear message rather than surfacing a cryptic
    // ERR_INVALID_URL later, on the first spec fetch or tool call.
    // eslint-disable-next-line no-new
    new URL(baseUrl);
  } catch {
    throw new Error(
      `MEALIE_BASE_URL is not a valid URL: ${JSON.stringify(rawBase)}. ` +
        "Use an absolute URL including the scheme, e.g. https://mealie.example.com.",
    );
  }
  return baseUrl;
}

function parseTimeout(env: NodeJS.ProcessEnv): number {
  const timeoutRaw = env.MEALIE_TIMEOUT?.trim();
  return timeoutRaw && /^\d+$/.test(timeoutRaw) ? Number(timeoutRaw) : 60_000;
}

function parseToolNameMax(env: NodeJS.ProcessEnv): number {
  const nameMaxRaw = env.MEALIE_TOOL_NAME_MAX?.trim();
  return nameMaxRaw && /^\d+$/.test(nameMaxRaw)
    ? Math.min(64, Math.max(16, Number(nameMaxRaw)))
    : DEFAULT_TOOL_NAME_MAX;
}

function parseRetries(env: NodeJS.ProcessEnv): number {
  const retriesRaw = env.MEALIE_RETRIES?.trim();
  return retriesRaw && /^\d+$/.test(retriesRaw)
    ? Math.min(MAX_RETRIES, Number(retriesRaw))
    : DEFAULT_RETRIES;
}

function parseOAuth(env: NodeJS.ProcessEnv): OAuthConfig | undefined {
  const oauthTokenUrl = env.MEALIE_OAUTH_TOKEN_URL?.trim();
  const oauthClientId = env.MEALIE_OAUTH_CLIENT_ID?.trim();
  const oauthClientSecret = env.MEALIE_OAUTH_CLIENT_SECRET?.trim();
  // Enable OAuth only when the full client-credentials triplet is present;
  // a partial config is treated as "not configured" rather than silently broken.
  return oauthTokenUrl && oauthClientId && oauthClientSecret
    ? {
        tokenUrl: oauthTokenUrl,
        clientId: oauthClientId,
        clientSecret: oauthClientSecret,
        scope: env.MEALIE_OAUTH_SCOPE?.trim() || undefined,
        audience: env.MEALIE_OAUTH_AUDIENCE?.trim() || undefined,
      }
    : undefined;
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  return {
    baseUrl: parseBaseUrl(env),
    token: env.MEALIE_API_TOKEN?.trim() || env.MEALIE_TOKEN?.trim() || undefined,
    oauth: parseOAuth(env),
    openapiUrl: env.MEALIE_OPENAPI_URL?.trim() || undefined,
    useBundledSpec: bool(env.MEALIE_USE_BUNDLED_SPEC),
    readOnly: bool(env.MEALIE_READ_ONLY),
    include: list(env.MEALIE_TOOLS),
    exclude: list(env.MEALIE_EXCLUDE_TOOLS),
    timeoutMs: parseTimeout(env),
    acceptLanguage: env.MEALIE_ACCEPT_LANGUAGE?.trim() || undefined,
    toolNameMax: parseToolNameMax(env),
    debug: bool(env.MEALIE_DEBUG),
    retries: parseRetries(env),
    allowedUploadDirs: list(env.MEALIE_ALLOWED_UPLOAD_DIRS),
  };
}

// Resolves the `Authorization` header sent to Mealie. The server supports two
// credential sources: a static long-lived token, or — taking precedence — an
// OAuth2 client-credentials grant whose access token is fetched, cached and
// refreshed against the IdP. Keeping this behind a small interface lets the
// HTTP client stay agnostic about where the bearer value comes from.

import type { Config, OAuthConfig } from "./config.js";

export interface TokenProvider {
  /**
   * Full `Authorization` header value (e.g. `Bearer <token>`), or undefined when
   * the server is unauthenticated. Pass `forceRefresh` to bypass any cache —
   * used to recover from a 401 caused by an expired/revoked access token.
   */
  authHeader(forceRefresh?: boolean): Promise<string | undefined>;
}

// Refresh a little before the IdP-stated expiry to absorb clock skew / latency.
const EXPIRY_MARGIN_MS = 60_000;
// Fallback lifetime when the token response omits `expires_in`.
const DEFAULT_LIFETIME_S = 3600;

interface TokenResponse {
  access_token?: string;
  token_type?: string;
  expires_in?: number;
}

/**
 * The token endpoint is named in every error this class throws, so strip
 * anything sensitive the operator may have put in it: a query string, or
 * `user:pass@` userinfo, which `origin` drops.
 *
 * Falls back to the raw value when it will not parse. Nothing validates
 * MEALIE_OAUTH_TOKEN_URL as a URL, so a misconfigured one must still produce the
 * "request failed" message that says what broke — not a bare ERR_INVALID_URL
 * thrown out of the sanitizer, before the request is even attempted.
 */
function safeTokenUrl(tokenUrl: string): string {
  try {
    const parsed = new URL(tokenUrl);
    return `${parsed.origin}${parsed.pathname}`;
  } catch {
    // SECURITY: Do not return the raw tokenUrl here, as it may contain sensitive credentials
    return "<invalid url>";
  }
}

class OAuthTokenProvider implements TokenProvider {
  private cached?: { header: string; expiresAt: number };
  /** In-flight fetch, shared so parallel tool calls don't stampede the token endpoint. */
  private inflight?: Promise<string>;

  constructor(
    private readonly oauth: OAuthConfig,
    private readonly timeoutMs: number,
  ) {}

  async authHeader(forceRefresh = false): Promise<string> {
    if (!forceRefresh && this.cached && Date.now() < this.cached.expiresAt) {
      return this.cached.header;
    }
    if (forceRefresh) this.cached = undefined;
    if (!this.inflight) {
      this.inflight = this.fetchToken().finally(() => {
        this.inflight = undefined;
      });
    }
    return this.inflight;
  }

  private async fetchToken(): Promise<string> {
    const body = new URLSearchParams({
      grant_type: "client_credentials",
      client_id: this.oauth.clientId,
      client_secret: this.oauth.clientSecret,
    });
    if (this.oauth.scope) body.append("scope", this.oauth.scope);
    if (this.oauth.audience) body.append("audience", this.oauth.audience);

    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
    let res: Response;
    let rawText: string;

    const safeUrl = safeTokenUrl(this.oauth.tokenUrl);

    try {
      res = await fetch(this.oauth.tokenUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          Accept: "application/json",
        },
        body,
        signal: controller.signal,
      });
      // SECURITY: Ensure body is read within the timeout window
      rawText = await res.text();
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      throw new Error(`OAuth token request to ${safeUrl} failed: ${reason}`);
    } finally {
      clearTimeout(timer);
    }

    if (!res.ok) {
      // SECURITY: Do not include rawText in the error message to avoid leaking sensitive information.
      throw new Error(
        `OAuth token request to ${safeUrl} returned HTTP ${res.status} ${res.statusText}`,
      );
    }

    let parsed: TokenResponse;
    try {
      parsed = JSON.parse(rawText) as TokenResponse;
    } catch {
      throw new Error(`OAuth token response from ${safeUrl} was not valid JSON.`);
    }
    if (!parsed || typeof parsed !== "object" || !parsed.access_token) {
      throw new Error(`OAuth token response from ${safeUrl} did not include an access_token.`);
    }

    const lifetimeMs = (parsed.expires_in ?? DEFAULT_LIFETIME_S) * 1000;
    const header = `${parsed.token_type?.trim() || "Bearer"} ${parsed.access_token}`;
    this.cached = { header, expiresAt: Date.now() + Math.max(0, lifetimeMs - EXPIRY_MARGIN_MS) };
    return header;
  }
}

class StaticTokenProvider implements TokenProvider {
  private readonly header: string;
  constructor(token: string) {
    this.header = `Bearer ${token}`;
  }
  async authHeader(): Promise<string> {
    return this.header;
  }
}

const ANONYMOUS: TokenProvider = { authHeader: async () => undefined };

/** Build the token provider for the given config. OAuth wins over a static token. */
export function createTokenProvider(config: Config): TokenProvider {
  if (config.oauth) return new OAuthTokenProvider(config.oauth, config.timeoutMs);
  if (config.token) return new StaticTokenProvider(config.token);
  return ANONYMOUS;
}

/** Whether a provider can refresh its credential (so a 401 retry is worth attempting). */
export function isRefreshable(config: Config): boolean {
  return Boolean(config.oauth);
}

import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import type { Config } from "./config.js";
import type { OpenApiDocument } from "./openapi-types.js";

export interface LoadedSpec {
  doc: OpenApiDocument;
  source: "live" | "bundled";
}

const here = dirname(fileURLToPath(import.meta.url));
// Bundled snapshot lives at the package root (one level above src/ or dist/).
const SNAPSHOT_PATH = join(here, "..", "openapi.snapshot.json");

function safeUrl(urlStr: string): string {
  try {
    const parsed = new URL(urlStr);
    return `${parsed.origin}${parsed.pathname}`;
  } catch {
    // SECURITY: Do not return the raw urlStr here, as it may contain sensitive credentials.
    // This is a deliberate mitigation for the "Sensitive Data Exposure in Request URL Logging Fallback"
    // vulnerability to ensure credentials are never leaked if URL parsing fails.
    return "<invalid url>";
  }
}

async function loadBundled(): Promise<OpenApiDocument> {
  const raw = await readFile(SNAPSHOT_PATH, "utf8");
  return JSON.parse(raw) as OpenApiDocument;
}

async function fetchLive(url: string, timeoutMs: number): Promise<OpenApiDocument> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, {
      signal: controller.signal,
      headers: { Accept: "application/json" },
    });
    if (!res.ok) {
      throw new Error(`HTTP ${res.status} ${res.statusText}`);
    }
    return (await res.json()) as OpenApiDocument;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Load the OpenAPI document that drives tool generation.
 *
 * Preference order:
 *  1. If `useBundledSpec` is set, use the snapshot shipped with the package.
 *  2. Otherwise fetch `${baseUrl}/openapi.json` (or `openapiUrl`) so tools match
 *     the exact Mealie version the user runs.
 *  3. On any failure, fall back to the bundled snapshot.
 */
export async function loadOpenApi(config: Config): Promise<LoadedSpec> {
  if (config.useBundledSpec) {
    return { doc: await loadBundled(), source: "bundled" };
  }

  const url = config.openapiUrl ?? `${config.baseUrl}/openapi.json`;
  try {
    const doc = await fetchLive(url, config.timeoutMs);
    if (!doc?.paths || typeof doc.paths !== "object") {
      throw new Error("response did not contain an OpenAPI `paths` object");
    }
    return { doc, source: "live" };
  } catch (err) {
    const reason = err instanceof Error ? err.message : String(err);
    process.stderr.write(
      `[mealie-mcp] Could not fetch live spec from ${safeUrl(url)} (${reason}); falling back to bundled snapshot.\n`,
    );
    return { doc: await loadBundled(), source: "bundled" };
  }
}

import { DEFAULT_TOOL_NAME_MAX, type Config } from "./config.js";
import { buildDefs, COMPONENT_REF_PREFIX, localize } from "./schema.js";
import {
  HTTP_METHODS,
  type HttpMethod,
  type JsonSchema,
  type OpenApiDocument,
  type OpenApiOperation,
  type OpenApiParameter,
} from "./openapi-types.js";

type BodyKind = "json" | "urlencoded" | "multipart";

interface OperationBody {
  kind: BodyKind;
  schema: JsonSchema | undefined;
  required: boolean;
  fileFields: string[];
}

export interface MealieTool {
  /** MCP tool name: `<category>_<operation>`, unique and <= 64 chars. */
  name: string;
  description: string;
  inputSchema: JsonSchema;
  /** Slugified first tag, used for include/exclude filtering. */
  category: string;
  method: HttpMethod;
  /** Path template containing `{param}` placeholders. */
  path: string;
  pathParams: string[];
  queryParams: Array<{ name: string; isArray: boolean }>;
  body?: {
    kind: BodyKind;
    required: boolean;
    /** Property names that carry file contents (multipart binary fields). */
    fileFields: string[];
  };
  deprecated: boolean;
  /** Internal precomputed set of fileFields to avoid allocating Set instances repeatedly. */
  _fileFieldsSet?: Set<string>;
}

function slug(value: string): string {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

/** Strip the FastAPI-generated `<path>_<method>` suffix off an operationId. */
function operationName(operationId: string | undefined, path: string, method: string): string {
  if (!operationId) return `${method}_${slug(path)}`;
  const suffix = `${path.replace(/\W/g, "_")}_${method}`;
  return operationId.endsWith(suffix) ? operationId.slice(0, -suffix.length) : operationId;
}

/** Collapse immediately repeated tokens, e.g. `recipe_recipe_get` -> `recipe_get`. */
function dedupeTokens(name: string): string {
  const parts = name.split("_");
  let result = "";
  let last = "";
  for (let i = 0; i < parts.length; i++) {
    const p = parts[i];
    if (p.length > 0 && p !== last) {
      if (result.length > 0) result += "_";
      result += p;
      last = p;
    }
  }
  return result;
}

function nameParts(op: OpenApiOperation, path: string, method: string): { category: string; base: string } {
  const category = slug(op.tags?.[0] ?? "misc");
  const base = dedupeTokens(operationName(op.operationId, path, method).replace(/_+/g, "_"));
  return { category, base };
}

/**
 * Build the (untruncated) tool name. Bare operation names (e.g.
 * `suggest_recipes`) are used as-is for brevity; names reused across routers
 * (e.g. `get_all`, `create_one`) are prefixed with their category to stay unique.
 */
function buildName(category: string, base: string, prefixed: boolean): string {
  const name = prefixed ? dedupeTokens(`${category}_${base}`.replace(/_+/g, "_")) : base;
  return name || "tool";
}

/** Truncate a name to `max` chars without leaving a dangling underscore. */
function clampName(name: string, max: number): string {
  if (name.length <= max) return name;
  return name.slice(0, max).replace(/_+$/, "") || name.slice(0, max);
}

function buildDescription(op: OpenApiOperation, path: string, method: string): string {
  const parts: string[] = [];
  if (op.summary) parts.push(op.summary);
  parts.push(`[${method.toUpperCase()} ${path}]`);
  if (op.description && op.description.trim() && op.description.trim() !== op.summary) {
    parts.push(op.description.trim());
  }
  if (op.deprecated) parts.unshift("(DEPRECATED)");
  let text = parts.join("\n");
  if (text.length > 2000) text = `${text.slice(0, 1997)}...`;
  return text;
}

/** Does a parameter schema permit an array value (so we repeat the query key)? */
export function schemaAllowsArray(schema: JsonSchema | undefined): boolean {
  if (!schema) return false;
  if (schema.type === "array") return true;
  for (const key of ["anyOf", "oneOf", "allOf"] as const) {
    const branch = schema[key];
    if (Array.isArray(branch) && branch.some((s) => schemaAllowsArray(s as JsonSchema))) return true;
  }
  return false;
}

/** Resolve a possibly-$ref'd schema to its target object (one hop) for inspection. */
export function resolveSchema(schema: JsonSchema | undefined, components: Record<string, JsonSchema>): JsonSchema | undefined {
  if (!schema) return undefined;
  const ref = schema.$ref;
  if (typeof ref === "string" && ref.startsWith(COMPONENT_REF_PREFIX)) {
    const name = ref.slice(COMPONENT_REF_PREFIX.length);
    if (name && components[name]) return components[name];
  }
  return schema;
}

/** Find multipart properties whose schema is binary (a file), incl. arrays of files. */
function findFileFields(schema: JsonSchema | undefined, components: Record<string, JsonSchema>): string[] {
  const resolved = resolveSchema(schema, components);
  const props = resolved?.properties as Record<string, JsonSchema> | undefined;
  if (!props) return [];
  const isBinary = (s: JsonSchema | undefined): boolean => {
    if (!s || typeof s !== "object") return false;
    // Mealie marks file fields with `contentMediaType` (e.g. application/octet-stream);
    // OpenAPI 3.1 also allows `format: binary`. Files may be a single value or an array.
    if (s.format === "binary") return true;
    if (typeof s.contentMediaType === "string") return true;
    if (isBinary(s.items as JsonSchema | undefined)) return true;
    for (const key of ["anyOf", "oneOf", "allOf"] as const) {
      const branch = s[key];
      if (Array.isArray(branch) && branch.some((b) => isBinary(b as JsonSchema))) return true;
    }
    return false;
  };
  return Object.entries(props)
    .filter(([, s]) => isBinary(s))
    .map(([k]) => k);
}

function pickBody(
  op: OpenApiOperation,
  components: Record<string, JsonSchema>,
): OperationBody | undefined {
  const content = op.requestBody?.content;
  if (!content) return undefined;
  const required = Boolean(op.requestBody?.required);

  if (content["application/json"]) {
    return { kind: "json", schema: content["application/json"].schema, required, fileFields: [] };
  }
  if (content["multipart/form-data"]) {
    const schema = content["multipart/form-data"].schema;
    return { kind: "multipart", schema, required, fileFields: findFileFields(schema, components) };
  }
  if (content["application/x-www-form-urlencoded"]) {
    return { kind: "urlencoded", schema: content["application/x-www-form-urlencoded"].schema, required, fileFields: [] };
  }
  // Unknown body type: treat the first available content as JSON-ish passthrough.
  const first = Object.values(content)[0];
  return first ? { kind: "json", schema: first.schema, required, fileFields: [] } : undefined;
}

function processParams(params: OpenApiParameter[]): {
  properties: Record<string, JsonSchema>;
  required: string[];
  pathParams: string[];
  queryParams: Array<{ name: string; isArray: boolean }>;
  rootSchemas: Array<JsonSchema | undefined>;
} {
  const properties: Record<string, JsonSchema> = {};
  const required: string[] = [];
  const pathParams: string[] = [];
  const queryParams: Array<{ name: string; isArray: boolean }> = [];
  const rootSchemas: Array<JsonSchema | undefined> = [];

  for (const param of params) {
    if (param.in !== "path" && param.in !== "query") continue; // headers/cookies handled globally
    const localized = localize(param.schema) ?? {};
    if (param.description && !localized.description) localized.description = param.description;
    properties[param.name] = localized;
    rootSchemas.push(param.schema);

    if (param.in === "path") {
      pathParams.push(param.name);
      required.push(param.name);
    } else {
      queryParams.push({ name: param.name, isArray: schemaAllowsArray(param.schema) });
      if (param.required) required.push(param.name);
    }
  }

  return { properties, required, pathParams, queryParams, rootSchemas };
}

function processBody(op: OpenApiOperation, body: OperationBody | undefined) {
  const properties: Record<string, JsonSchema> = {};
  const required: string[] = [];
  const rootSchemas: Array<JsonSchema | undefined> = [];

  if (body?.schema) {
    const bodySchema = localize(body.schema) ?? {};
    if (op.requestBody?.description && !bodySchema.description) {
      bodySchema.description = op.requestBody.description;
    }
    if (body.kind === "multipart" && body.fileFields.length > 0) {
      const note = `File fields (${body.fileFields.join(", ")}) must be absolute paths to local files to upload.`;
      bodySchema.description = bodySchema.description ? `${bodySchema.description} ${note}` : note;
    }
    properties.body = bodySchema;
    rootSchemas.push(body.schema);
    if (body.required) required.push("body");
  }

  return { properties, required, rootSchemas };
}

function buildInputSchema(
  op: OpenApiOperation,
  params: OpenApiParameter[],
  body: OperationBody | undefined,
  components: Record<string, JsonSchema>,
  defsCache: Map<string, JsonSchema>,
): { inputSchema: JsonSchema; pathParams: string[]; queryParams: Array<{ name: string; isArray: boolean }> } {
  const parsedParams = processParams(params);
  const parsedBody = processBody(op, body);

  const properties: Record<string, JsonSchema> = { ...parsedParams.properties, ...parsedBody.properties };
  const required: string[] = [...parsedParams.required, ...parsedBody.required];
  const rootSchemas: Array<JsonSchema | undefined> = [...parsedParams.rootSchemas, ...parsedBody.rootSchemas];

  const inputSchema: JsonSchema = { type: "object", properties };
  if (required.length > 0) inputSchema.required = required;
  inputSchema.additionalProperties = false;

  const defs = buildDefs(rootSchemas, components, defsCache);
  if (defs) inputSchema.$defs = defs;

  return { inputSchema, pathParams: parsedParams.pathParams, queryParams: parsedParams.queryParams };
}

interface RawEntry {
  path: string;
  method: HttpMethod;
  op: OpenApiOperation;
  params: OpenApiParameter[];
  body: OperationBody | undefined;
  category: string;
  base: string;
}

function collectOperations(
  doc: OpenApiDocument,
  components: Record<string, JsonSchema>,
): { entries: RawEntry[]; baseCounts: Record<string, number> } {
  const entries: RawEntry[] = [];
  const baseCounts: Record<string, number> = {};
  for (const path in doc.paths) {
    const item = doc.paths[path]!;
    const sharedParams = item.parameters ?? [];
    for (const method of HTTP_METHODS) {
      const op = item[method];
      if (!op) continue;
      const params = [...sharedParams, ...(op.parameters ?? [])];
      const body = pickBody(op, components);
      const { category, base } = nameParts(op, path, method);
      baseCounts[base] = (baseCounts[base] ?? 0) + 1;
      entries.push({ path, method, op, params, body, category, base });
    }
  }
  return { entries, baseCounts };
}

function resolveToolName(
  entry: RawEntry,
  baseCounts: Record<string, number>,
  usedNames: Set<string>,
  nameMax: number,
): string {
  const rawName = clampName(buildName(entry.category, entry.base, baseCounts[entry.base] > 1), nameMax);
  let name = rawName;
  for (let i = 2; usedNames.has(name); i++) {
    const suffix = `_${i}`;
    name = `${clampName(rawName, nameMax - suffix.length)}${suffix}`;
  }
  usedNames.add(name);
  return name;
}

function buildTool(
  entry: RawEntry,
  baseCounts: Record<string, number>,
  usedNames: Set<string>,
  components: Record<string, JsonSchema>,
  defsCache: Map<string, JsonSchema>,
  nameMax: number,
): MealieTool {
  const name = resolveToolName(entry, baseCounts, usedNames, nameMax);

  const { inputSchema, pathParams, queryParams } = buildInputSchema(
    entry.op,
    entry.params,
    entry.body,
    components,
    defsCache,
  );

  return {
    name,
    description: buildDescription(entry.op, entry.path, entry.method),
    inputSchema,
    category: entry.category,
    method: entry.method,
    path: entry.path,
    pathParams,
    queryParams,
    body: entry.body
      ? { kind: entry.body.kind, required: entry.body.required, fileFields: entry.body.fileFields }
      : undefined,
    deprecated: Boolean(entry.op.deprecated),
    _fileFieldsSet: entry.body ? new Set(entry.body.fileFields) : undefined,
  };
}

function buildTools(
  entries: RawEntry[],
  baseCounts: Record<string, number>,
  components: Record<string, JsonSchema>,
  nameMax: number,
): MealieTool[] {
  const tools: MealieTool[] = [];
  const usedNames = new Set<string>();
  const defsCache = new Map<string, JsonSchema>();
  for (const entry of entries) {
    tools.push(buildTool(entry, baseCounts, usedNames, components, defsCache, nameMax));
  }

  return tools;
}

/** Generate one MealieTool per operation in the OpenAPI document. */
export function generateTools(doc: OpenApiDocument, nameMax: number = DEFAULT_TOOL_NAME_MAX): MealieTool[] {
  const components = doc.components?.schemas ?? {};

  // First pass: collect operations and count how often each base name occurs,
  // so we only prepend the category to names that would otherwise collide.
  const { entries, baseCounts } = collectOperations(doc, components);

  // Second pass: build tools with finalized, unique names.
  return buildTools(entries, baseCounts, components, nameMax);
}

type FilterConditions = { exact: Set<string>; prefixes: string[] };

/**
 * ⚡ Bolt: Precomputing the exact lowercase and prefix match strings avoids
 * repeatedly calling `toLowerCase()` and allocating template strings for
 * every filter rule against every generated tool during initialization.
 */
function buildConditions(entries: string[]): FilterConditions {
  const exact = new Set<string>();
  const prefixes: string[] = [];
  for (const e of entries) {
    const lower = e.toLowerCase();
    exact.add(lower);
    prefixes.push(`${lower}_`);
  }
  return { exact, prefixes };
}

function matches(tool: MealieTool, conditions: FilterConditions): boolean {
  if (conditions.exact.has(tool.name) || conditions.exact.has(tool.category)) {
    return true;
  }
  for (const prefix of conditions.prefixes) {
    if (tool.name.startsWith(prefix) || tool.category.startsWith(prefix)) {
      return true;
    }
  }
  return false;
}

/**
 * Endpoints with essentially no use to an LLM client: account flows the MCP
 * credential already replaces or that need a browser/email, a healthcheck text
 * route, SSE stream duplicates of plain JSON endpoints, and opaque binary
 * downloads the client can only summarize.
 * (The `Users: Authentication` category is intentionally kept — the server can
 * authenticate via OAuth, so those routes are relevant.)
 */
export const DEFAULT_EXCLUDE: string[] = [
  "users_passwords", // forgot_password / reset_password (email-link flow)
  "register_new_user", // public signup
  "get_validation_text", // /api/media/docker/validate.txt healthcheck
  "create_recipe_from_html_or_json_stream", // SSE duplicate of create_recipe_from_html_or_json
  "parse_recipe_url_stream", // SSE duplicate of parse_recipe_url
  "get_exported_data", // zip export (opaque bytes)
  "get_exported_data_token", // zip download (opaque bytes)
  "get_shared_recipe_as_zip", // zip download (opaque bytes)
  "download_file", // /api/utils/download (opaque bytes)
];

/**
 * Admin / server-ops endpoints (backups, maintenance, multi-tenant user/group/
 * household management, debug, email config, AI providers). Powerful, rarely
 * what a recipe assistant needs, and a security footgun, so they are never
 * exposed. Matches every `Admin: *` category slug.
 */
const ADMIN_EXCLUDE: string[] = ["admin"];

/**
 * Tools that are *never* exposed, regardless of user config. This is the safe
 * baseline: users can narrow further via MEALIE_TOOLS / MEALIE_EXCLUDE_TOOLS,
 * but cannot re-enable anything listed here.
 */
export const HARD_EXCLUDE: string[] = [...DEFAULT_EXCLUDE, ...ADMIN_EXCLUDE];

/** Apply the hard-exclude baseline, then read-only / include / exclude filters from config. */
export function filterTools(tools: MealieTool[], config: Config): MealieTool[] {
  // Baseline trim is unconditional and applied first so user filters can only
  // ever subtract from it, never add a hard-excluded tool back.
  const hardExcludeConditions = buildConditions(HARD_EXCLUDE);
  const hasInclude = config.include.length > 0;
  const includeConditions = hasInclude ? buildConditions(config.include) : null;
  const hasExclude = config.exclude.length > 0;
  const excludeConditions = hasExclude ? buildConditions(config.exclude) : null;

  return tools.filter((t) => {
    if (matches(t, hardExcludeConditions)) return false;
    if (config.readOnly && t.method !== "get") return false;
    if (includeConditions && !matches(t, includeConditions)) return false;
    if (excludeConditions && matches(t, excludeConditions)) return false;
    return true;
  });
}

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
  type CallToolResult,
  type CallToolRequest,
} from "@modelcontextprotocol/sdk/types.js";
import type { Config } from "./config.js";
import type { TokenProvider } from "./auth.js";
import { executeTool } from "./http-client.js";
import type { MealieTool } from "./tools.js";

export const SERVER_NAME = "mealie-mcp";

export function createServer(config: Config, tools: MealieTool[], version: string, auth: TokenProvider): Server {
  // ⚡ Bolt: Use for...of to initialize the Map instead of Map(arr.map(...))
  // to avoid intermediate array and tuple allocations overhead.
  const byName = new Map<string, MealieTool>();
  for (const t of tools) byName.set(t.name, t);

  const server = new Server(
    { name: SERVER_NAME, version },
    { capabilities: { tools: {} } },
  );

  // ⚡ Bolt: Precompute the tool list response once since the tools array is static
  // after server creation. This avoids allocating a new array and hundreds of objects
  // on every ListToolsRequest, reducing GC churn and latency for frequent polling.
  const cachedListToolsResponse = {
    tools: tools.map((t) => ({
      name: t.name,
      description: t.description,
      inputSchema: t.inputSchema as { type: "object"; [k: string]: unknown },
    })),
  };

  server.setRequestHandler(ListToolsRequestSchema, async () => cachedListToolsResponse);

  server.setRequestHandler(CallToolRequestSchema, (request) =>
    handleToolCall(request, config, byName, auth)
  );

  return server;
}

async function handleToolCall(
  request: CallToolRequest,
  config: Config,
  byName: Map<string, MealieTool>,
  auth: TokenProvider
): Promise<CallToolResult> {
  const { name, arguments: args } = request.params;
  const tool = byName.get(name);
  if (!tool) {
    return {
      content: [{ type: "text", text: `Unknown tool: ${name}` }],
      isError: true,
    };
  }
  try {
    const result = await executeTool(config, tool, (args ?? {}) as Record<string, unknown>, auth);
    return result;
  } catch (err) {
    const reason = err instanceof Error ? err.message : String(err);
    return {
      content: [{ type: "text", text: `Error executing ${name}: ${reason}` }],
      isError: true,
    };
  }
}

import type { JsonSchema } from "./openapi-types.js";

export const COMPONENT_REF_PREFIX = "#/components/schemas/";

/**
 * Deep clone a JSON-compatible value.
 *
 * ⚡ Bolt: Custom recursive cloning avoids the heavy serialization overhead
 * of JSON.parse(JSON.stringify(...)), performing ~5x faster in tight loops.
 */
export function clone<T>(value: T): T {
  if (value === null || typeof value !== "object") return value;
  if (Array.isArray(value)) {
    const len = value.length;
    const arr = new Array(len);
    for (let i = 0; i < len; i++) {
      arr[i] = clone(value[i]);
    }
    // ⚡ Bolt: Fast pre-allocated array loop replaces Array.prototype.map() to
    // avoid allocating a callback function and an iterator for every array
    // nested in the schema, boosting clone performance by ~15-20%.
    return arr as unknown as T;
  }
  const res = {} as T;
  const keys = Object.keys(value);
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    if (k === "__proto__" || k === "constructor" || k === "prototype") continue;
    res[k as keyof T] = clone(value[k as keyof T]);
  }
  return res;
}

/**
 * Walk a schema node and collect every `#/components/schemas/<name>` it
 * references, transitively, by following into the referenced components.
 */
function collectRefs(
  node: unknown,
  components: Record<string, JsonSchema>,
  seen: Set<string>,
): void {
  if (Array.isArray(node)) {
    for (const item of node) collectRefs(item, components, seen);
    return;
  }
  if (!node || typeof node !== "object") return;

  const obj = node as Record<string, unknown>;
  if (typeof obj.$ref === "string" && obj.$ref.startsWith(COMPONENT_REF_PREFIX)) {
    const name = obj.$ref.slice(COMPONENT_REF_PREFIX.length);
    if (name && !seen.has(name)) {
      seen.add(name);
      if (components[name]) collectRefs(components[name], components, seen);
    }
  }

  // ⚡ Bolt: Using for...in avoids Object.entries() which allocates an array
  // of all key-value pairs on every recursive call, severely hurting performance.
  for (const key in obj) {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
    if (key === "$ref") continue;
    collectRefs(obj[key], components, seen);
  }
}

/** Rewrite `#/components/schemas/X` refs to local `#/$defs/X` refs (in place). */
function rewriteRefs(node: unknown): void {
  if (Array.isArray(node)) {
    for (const item of node) rewriteRefs(item);
    return;
  }
  if (!node || typeof node !== "object") return;

  const obj = node as Record<string, unknown>;
  if (typeof obj.$ref === "string" && obj.$ref.startsWith(COMPONENT_REF_PREFIX)) {
    const name = obj.$ref.slice(COMPONENT_REF_PREFIX.length);
    if (name) obj.$ref = `#/$defs/${name}`;
  }

  // ⚡ Bolt: Using for...in avoids Object.values() which allocates an array
  // of all values on every recursive call.
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      if (key !== "$ref") rewriteRefs(obj[key]);
    }
  }
}

/**
 * Given a set of root schemas, build the `$defs` map containing the transitive
 * closure of component schemas they reference, with all refs rewritten to
 * `#/$defs/...`. Returns `undefined` when nothing is referenced.
 *
 * ⚡ Bolt: Added a cache map parameter. The cache allows reusing the localized
 * representation of component schemas. Reusing the clones in `generateTools` avoids
 * redundant deep clones across the tool schema definitions, improving generation speed.
 */
export function buildDefs(
  roots: Array<JsonSchema | undefined>,
  components: Record<string, JsonSchema>,
  cache?: Map<string, JsonSchema>,
): Record<string, JsonSchema> | undefined {
  const seen = new Set<string>();
  for (const root of roots) {
    if (root) collectRefs(root, components, seen);
  }
  if (seen.size === 0) return undefined;

  const defs: Record<string, JsonSchema> = {};
  for (const name of seen) {
    if (cache?.has(name)) {
      defs[name] = cache.get(name)!;
      continue;
    }
    const schema = components[name];
    if (!schema) continue;
    const copy = clone(schema);
    rewriteRefs(copy);
    defs[name] = copy;
    if (cache) cache.set(name, copy);
  }
  return defs;
}

/** Clone a schema and rewrite its component refs to local `$defs` refs. */
export function localize(schema: JsonSchema | undefined): JsonSchema | undefined {
  if (!schema) return undefined;
  const copy = clone(schema);
  rewriteRefs(copy);
  return copy;
}

// Minimal structural types for the subset of OpenAPI 3.1 that Mealie emits.

export type JsonSchema = Record<string, unknown>;

export interface OpenApiParameter {
  name: string;
  in: "query" | "path" | "header" | "cookie";
  required?: boolean;
  description?: string;
  schema?: JsonSchema;
}

interface OpenApiMediaType {
  schema?: JsonSchema;
}

interface OpenApiRequestBody {
  required?: boolean;
  description?: string;
  content?: Record<string, OpenApiMediaType>;
}

export interface OpenApiOperation {
  operationId?: string;
  summary?: string;
  description?: string;
  tags?: string[];
  deprecated?: boolean;
  parameters?: OpenApiParameter[];
  requestBody?: OpenApiRequestBody;
  responses?: Record<string, unknown>;
  security?: Array<Record<string, unknown>>;
}

export type HttpMethod = "get" | "post" | "put" | "patch" | "delete";

type OpenApiPathItem = Partial<Record<HttpMethod, OpenApiOperation>> & {
  parameters?: OpenApiParameter[];
};

export interface OpenApiDocument {
  openapi: string;
  info: { title?: string; version?: string; description?: string };
  paths: Record<string, OpenApiPathItem>;
  components?: {
    schemas?: Record<string, JsonSchema>;
  };
}

export const HTTP_METHODS: HttpMethod[] = ["get", "post", "put", "patch", "delete"];

import { realpath, stat } from "node:fs/promises";
import * as fs from "node:fs";
import { basename, extname, sep } from "node:path";
import { Readable } from "node:stream";
import type { Config } from "./config.js";
import { isRefreshable, type TokenProvider } from "./auth.js";
import type { MealieTool } from "./tools.js";

type ContentBlock =
  | { type: "text"; text: string }
  | { type: "image"; data: string; mimeType: string };

export interface ToolResult {
  content: ContentBlock[];
  isError?: boolean;
  [key: string]: unknown;
}

const MAX_TEXT = 100_000;

export function safeUrl(urlStr: string): string {
  try {
    const parsed = new URL(urlStr);
    return `${parsed.origin}${parsed.pathname}`;
  } catch {
    // SECURITY: Do not return the raw urlStr here, as it may contain sensitive credentials.
    // This is a deliberate mitigation for the "Sensitive Data Exposure in Request URL Logging Fallback"
    // vulnerability to ensure credentials are never leaked if URL parsing fails.
    return "<invalid url>";
  }
}

// `basename()` has already dropped the directory part, so this is not about
// containment — the allowlist check in `readUpload` owns that. It is about not
// forwarding a name Mealie has to cope with: control characters, quotes, and
// characters that are illegal in a filename on the far side.
function sanitizeFilename(name: string): string {
  const safe = name.replace(/[\x00-\x1F\x7F<>:"/\\|?*]/g, "_");
  // A name that was nothing but stripped characters, or only dots, is no name.
  return !safe || /^\.+$/.test(safe) ? "upload.bin" : safe;
}

// Statuses worth retrying for idempotent requests: rate-limiting and transient
// server-side failures. 4xx (other than 429) are the caller's fault and repeating
// them just wastes time.
const RETRYABLE_STATUS = new Set([429, 500, 502, 503, 504]);
const RETRY_BASE_DELAY_MS = 250;

const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB

// `fs.openAsBlob` hands `fetch` a file-backed Blob it can stream straight off
// disk, so a 50MB upload never lands in the V8 heap. It arrived in Node 19.8
// and `engines` still allows 18, where we fall back to the stream-backed
// stand-in below, which keeps the same streaming property.
// It has to be read off the namespace rather than imported by name: a static
// named import of a missing builtin export is a link-time SyntaxError, which
// would take down the whole server on Node 18 instead of just this one path.
const openAsBlob: typeof fs.openAsBlob | undefined =
  typeof fs.openAsBlob === "function" ? fs.openAsBlob : undefined;

// Every part used to go out as a typeless Blob, which multipart serializes as
// `application/octet-stream` — so an uploaded JPEG announced itself as opaque
// bytes. Server-side handlers that branch on the part's content type (image
// uploads, the recipe-from-image endpoints that hand the file to an AI
// provider) have nothing useful to branch on. Cover the formats Mealie's
// upload endpoints accept; anything else keeps the octet-stream default.
const MIME_TYPES = new Map<string, string>([
  [".avif", "image/avif"],
  [".bmp", "image/bmp"],
  [".gif", "image/gif"],
  [".heic", "image/heic"],
  [".jpeg", "image/jpeg"],
  [".jpg", "image/jpeg"],
  [".png", "image/png"],
  [".svg", "image/svg+xml"],
  [".tif", "image/tiff"],
  [".tiff", "image/tiff"],
  [".webp", "image/webp"],
  [".csv", "text/csv"],
  [".html", "text/html"],
  [".json", "application/json"],
  [".md", "text/markdown"],
  [".pdf", "application/pdf"],
  [".txt", "text/plain"],
  [".xml", "application/xml"],
  [".yaml", "application/yaml"],
  [".yml", "application/yaml"],
  [".zip", "application/zip"],
]);

function mimeTypeFor(filePath: string): string {
  return MIME_TYPES.get(extname(filePath).toLowerCase()) ?? "application/octet-stream";
}

function text(value: string): ContentBlock {
  return { type: "text", text: value };
}

function debugLog(config: Config, message: string): void {
  if (config.debug) process.stderr.write(`[mealie-mcp] ${message}\n`);
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Exponential backoff for the Nth retry (1-based): 250ms, 500ms, 1s, … */
function backoffMs(attempt: number): number {
  return RETRY_BASE_DELAY_MS * 2 ** (attempt - 1);
}

function truncate(value: string): string {
  if (value.length <= MAX_TEXT) return value;
  return `${value.slice(0, MAX_TEXT)}\n\n…[truncated ${value.length - MAX_TEXT} characters]`;
}

function buildUrl(config: Config, tool: MealieTool, args: Record<string, unknown>): string {
  let path = tool.path;
  for (const name of tool.pathParams) {
    const value = args[name];
    if (value === undefined || value === null) {
      throw new Error(`Missing required path parameter: ${name}`);
    }
    path = path.replace(`{${name}}`, encodeURIComponent(String(value)));
  }

  // Resolve against the base rather than concatenating. `baseUrl + path` lets a
  // spec-supplied path beginning with `@` reparse the host: "https://mealie.example"
  // + "@evil.com/x" is a URL whose host is evil.com. The two-argument form cannot
  // be steered that way.
  //
  // Both sides need adjusting for that form to preserve a base with a subpath:
  // the base must end in `/` or its last segment is dropped, and the path must
  // not start with `/` or it resolves against the origin and drops the subpath.
  const base = config.baseUrl.endsWith("/") ? config.baseUrl : `${config.baseUrl}/`;
  const url = new URL(path.replace(/^\/+/, ""), base);

  // SECURITY: Assert that the generated URL origin strictly matches the base origin
  // to prevent Server-Side Request Forgery (SSRF) via protocol-relative paths or absolute URLs.
  if (url.origin !== new URL(base).origin) {
    throw new Error("SSRF attack detected: URL origin mismatch");
  }

  for (const { name } of tool.queryParams) {
    const value = args[name];
    if (value === undefined || value === null) continue;
    // Array values are always expanded as repeated `key=` pairs, regardless of
    // whether the schema declared the parameter as an array.
    if (Array.isArray(value)) {
      for (const item of value) url.searchParams.append(name, scalar(item));
    } else {
      url.searchParams.append(name, scalar(value));
    }
  }
  return url.toString();
}

function scalar(value: unknown): string {
  if (typeof value === "string") return value;
  if (typeof value === "object") return JSON.stringify(value);
  return String(value);
}

/**
 * Resolve the allowlist once per request. Each entry is realpath'd so a
 * symlinked allowed directory still matches, and given a trailing separator so
 * `/srv/uploads` cannot be satisfied by `/srv/uploads-evil`. Entries that do
 * not resolve (typo, not mounted) are dropped rather than throwing: a bad entry
 * must never widen the allowlist, and dropping it can only narrow.
 */
async function resolveAllowedDirs(dirs: string[]): Promise<string[]> {
  const resolved = await Promise.all(
    dirs.map(async (dir) => {
      try {
        const real = await realpath(dir);
        return real.endsWith(sep) ? real : real + sep;
      } catch {
        return undefined;
      }
    }),
  );
  return resolved.filter((dir): dir is string => dir !== undefined);
}

export async function readUpload(
  filePath: string,
  allowedDirs: string[],
): Promise<{ filePath: string; blob: Blob }> {
  // SECURITY: the path comes from the model, so resolve symlinks before doing
  // anything else and then use only the real path. Checking the path as given
  // and reading it afterwards would let a symlink inside an allowed directory
  // point anywhere on the box — a lexical `resolve()` cannot see through one.
  let realPath: string;
  try {
    realPath = await realpath(filePath);
  } catch (err) {
    // Paths here come from a model, so a bare ENOENT/EACCES is worth restating
    // in terms of the upload it broke.
    const reason = err instanceof Error ? err.message : String(err);
    throw new Error(`Upload failed: cannot read ${filePath} (${reason}).`);
  }

  if (!allowedDirs.some((dir) => (realPath + sep).startsWith(dir))) {
    // Deliberately reports the real path: when a symlink is what pushed the
    // upload out of bounds, naming only the link makes the refusal baffling.
    throw new Error(
      `Upload failed: ${filePath} resolves to ${realPath}, which is outside MEALIE_ALLOWED_UPLOAD_DIRS.`,
    );
  }

  // SECURITY: Validate file type and size before reading to prevent DoS (e.g., /dev/urandom or huge files)
  const stats = await stat(realPath);
  if (!stats.isFile()) {
    throw new Error(`Upload failed: ${filePath} is not a regular file.`);
  }
  if (stats.size > MAX_FILE_SIZE) {
    throw new Error(`Upload failed: ${filePath} exceeds the maximum allowed size of 50MB.`);
  }

  // Name and MIME type come from the path the caller asked for; the bytes come
  // from the real path that was actually vetted.
  const type = mimeTypeFor(filePath);
  // An `openAsBlob` part is lazy: the bytes are pulled during `fetch`, so the
  // file has to stay put until the request goes out.
  if (openAsBlob) return { filePath, blob: await openAsBlob(realPath, { type }) };

  // Fallback for Node 18: create a duck-typed Blob that streams the file
  // to avoid loading up to 50MB into the V8 heap at once.
  const blob = {
    [Symbol.toStringTag]: "Blob",
    type,
    size: stats.size,
    stream() {
      return Readable.toWeb(fs.createReadStream(realPath)) as ReadableStream;
    },
    arrayBuffer() {
      return new Response((this as any).stream()).arrayBuffer();
    },
    slice() {
      return this;
    },
    text() {
      return new Response((this as any).stream()).text();
    },
  } as unknown as Blob;

  return { filePath, blob };
}

async function buildMultipart(
  config: Config,
  tool: MealieTool,
  body: Record<string, unknown>,
): Promise<FormData> {
  const form = new FormData();
  const fileFields = tool._fileFieldsSet ?? new Set(tool.body?.fileFields ?? []);
  // SECURITY: Fail closed. If no upload directories are explicitly allowed,
  // uploads are refused to prevent arbitrary local file reads.
  const allowedDirs = await resolveAllowedDirs(config.allowedUploadDirs);

  // ⚡ Bolt: Process files concurrently to overlap I/O latency, but return
  // synchronous closures to execute sequentially and preserve append order.
  const operations = await Promise.all(
    Object.entries(body).map(async ([key, value]) => {
      if (value === undefined || value === null) return () => {};
      if (fileFields.has(key)) {
        const paths = Array.isArray(value) ? value : [value];
        const files = await Promise.all(paths.map((p) => readUpload(String(p), allowedDirs)));
        return () => {
          for (const { filePath, blob } of files) {
            form.append(key, blob, sanitizeFilename(basename(filePath)));
          }
        };
      } else if (Array.isArray(value)) {
        return () => {
          for (const item of value) form.append(key, scalar(item));
        };
      } else {
        return () => {
          form.append(key, scalar(value));
        };
      }
    })
  );

  for (const apply of operations) {
    apply();
  }

  return form;
}

async function readImageBody(res: Response, contentType: string): Promise<{ blocks: ContentBlock[]; raw: string }> {
  const buf = Buffer.from(await res.arrayBuffer());
  return {
    blocks: [{ type: "image", data: buf.toString("base64"), mimeType: contentType.split(";")[0] }],
    raw: `[image ${contentType} ${buf.length} bytes]`,
  };
}

async function readJsonBody(res: Response): Promise<{ blocks: ContentBlock[]; raw: string }> {
  const raw = await res.text();
  // ⚡ Bolt: Avoid expensive parsing and stringifying if the result is going
  // to be heavily truncated anyway. MAX_TEXT * 5 is an arbitrary threshold
  // indicating the raw JSON is already huge (e.g. 500KB+).
  if (raw.length > MAX_TEXT * 5) {
    return { blocks: [text(truncate(raw))], raw };
  }
  try {
    const pretty = JSON.stringify(JSON.parse(raw), null, 2);
    return { blocks: [text(truncate(pretty))], raw };
  } catch {
    return { blocks: [text(truncate(raw))], raw };
  }
}

async function readTextBody(res: Response): Promise<{ blocks: ContentBlock[]; raw: string }> {
  const raw = await res.text();
  return { blocks: [text(truncate(raw))], raw };
}

async function readBody(res: Response): Promise<{ blocks: ContentBlock[]; raw: string }> {
  const contentType = res.headers.get("content-type") ?? "";

  if (res.status === 204 || res.headers.get("content-length") === "0") {
    // Only call an empty body a "success"; on an error status the caller
    // prepends the HTTP status, so a neutral note reads correctly there.
    const message = res.ok ? `Success (HTTP ${res.status}, no content).` : "(no response body)";
    return { blocks: [text(message)], raw: "" };
  }

  if (contentType.startsWith("image/")) {
    return readImageBody(res, contentType);
  }

  if (contentType.includes("application/json")) {
    return readJsonBody(res);
  }

  if (contentType.startsWith("text/") || contentType.includes("xml") || contentType.includes("yaml")) {
    return readTextBody(res);
  }

  // Other binary payloads (zip, pdf, octet-stream): summarize instead of dumping base64.
  const buf = Buffer.from(await res.arrayBuffer());
  return {
    blocks: [text(`Received ${buf.length} bytes of binary data (${contentType || "unknown type"}).`)],
    raw: `[binary ${buf.length} bytes]`,
  };
}

async function buildPayload(
  config: Config,
  tool: MealieTool,
  args: Record<string, unknown>,
  headers: Record<string, string>,
): Promise<string | URLSearchParams | FormData | undefined> {
  if (!tool.body || args.body === undefined || args.body === null) {
    return undefined;
  }

  const bodyValue = args.body as Record<string, unknown>;
  if (tool.body.kind === "json") {
    headers["Content-Type"] = "application/json";
    return JSON.stringify(bodyValue);
  }

  if (tool.body.kind === "urlencoded") {
    const params = new URLSearchParams();
    for (const [k, v] of Object.entries(bodyValue)) {
      if (v !== undefined && v !== null) params.append(k, scalar(v));
    }
    return params;
  }

  return await buildMultipart(config, tool, bodyValue);
}

async function performRequest(
  config: Config,
  url: string,
  method: string,
  headers: Record<string, string>,
  payload: string | URLSearchParams | FormData | undefined,
): Promise<{ res: Response; body: { blocks: ContentBlock[]; raw: string } }> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), config.timeoutMs);
  try {
    const res = await fetch(url, {
      method,
      headers,
      body: payload,
      signal: controller.signal,
    });
    // SECURITY: Ensure body is read within the timeout window (prevent Slow Loris DoS attacks)
    const body = await readBody(res);
    return { res, body };
  } finally {
    clearTimeout(timer);
  }
}

async function executeWithRetry(
  config: Config,
  tool: MealieTool,
  url: string,
  method: string,
  maxAttempts: number,
  send: (forceRefresh: boolean) => Promise<{ res: Response; body: { blocks: ContentBlock[]; raw: string } }>,
): Promise<ToolResult> {
  for (let attempt = 1; ; attempt++) {
    let res: Response;
    let bodyResult: { blocks: ContentBlock[]; raw: string };
    try {
      ({ res, body: bodyResult } = await send(false));
      // A 401 may mean the OAuth access token expired mid-flight; force one refresh and retry.
      if (res.status === 401 && isRefreshable(config)) {
        ({ res, body: bodyResult } = await send(true));
      }
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      if (attempt < maxAttempts) {
        const delay = backoffMs(attempt);
        debugLog(config, `${method} ${tool.path} failed (${reason}); retrying in ${delay}ms`);
        await sleep(delay);
        continue;
      }
      debugLog(config, `${method} ${tool.path} → network error: ${reason}`);
      return { content: [text(`Request to ${method} ${safeUrl(url)} failed: ${reason}`)], isError: true };
    }

    debugLog(config, `${method} ${tool.path} → ${res.status}`);

    if (RETRYABLE_STATUS.has(res.status) && attempt < maxAttempts) {
      const delay = backoffMs(attempt);
      debugLog(config, `${method} ${tool.path} → ${res.status}; retrying in ${delay}ms`);
      await sleep(delay);
      continue;
    }

    const { blocks } = bodyResult;
    if (!res.ok) {
      const detail = blocks.map((b) => (b.type === "text" ? b.text : "[binary]")).join("\n");
      return {
        content: [text(`HTTP ${res.status} ${res.statusText} from ${method} ${tool.path}\n${detail}`)],
        isError: true,
      };
    }

    return { content: blocks };
  }
}

export async function executeTool(
  config: Config,
  tool: MealieTool,
  args: Record<string, unknown>,
  auth: TokenProvider,
): Promise<ToolResult> {
  const url = buildUrl(config, tool, args);

  const baseHeaders: Record<string, string> = { Accept: "application/json" };
  if (config.acceptLanguage) baseHeaders["Accept-Language"] = config.acceptLanguage;

  const payload = await buildPayload(config, tool, args, baseHeaders);

  const send = async (forceRefresh: boolean): Promise<{ res: Response; body: { blocks: ContentBlock[]; raw: string } }> => {
    const headers = { ...baseHeaders };
    const authValue = await auth.authHeader(forceRefresh);
    if (authValue) headers.Authorization = authValue;

    return performRequest(config, url, tool.method.toUpperCase(), headers, payload);
  };

  const method = tool.method.toUpperCase();
  // Only GET is retried automatically: it is idempotent, so a repeat is safe.
  const maxAttempts = tool.method === "get" ? (config.retries ?? 0) + 1 : 1;

  return executeWithRetry(config, tool, url, method, maxAttempts, send);
}
